#!/usr/bin/env python3
"""stringslite.py -- a minimal strings(1) clone.

Scans a binary file for runs of at least MIN printable ASCII characters
(default 4) and prints each run on its own line.  With ``-t x`` each line
is prefixed with the hexadecimal file offset of the run, like
``strings -t x``.
"""

import argparse
import sys


def find_strings(data: bytes, min_len: int):
    """Yield (offset, string) for every run of >= min_len printable ASCII bytes."""
    runs = []
    start = None
    for i, byte in enumerate(data):
        if 0x20 <= byte <= 0x7E:
            if start is None:
                start = i
        else:
            if start is not None and i - start >= min_len:
                runs.append((start, data[start:i].decode("ascii")))
            start = None
    if start is not None and len(data) - start >= min_len:
        runs.append((start, data[start:].decode("ascii")))
    return runs


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Print runs of printable ASCII characters in FILE."
    )
    parser.add_argument("file", help="binary file to scan ('-' for stdin)")
    parser.add_argument(
        "-n",
        metavar="MIN",
        type=int,
        default=4,
        help="minimum length of printed strings (default: 4)",
    )
    parser.add_argument(
        "-t",
        metavar="RADIX",
        choices=["d", "o", "x"],
        help="prefix each line with the file offset (d=decimal, o=octal, x=hex)",
    )
    args = parser.parse_args(argv)

    try:
        if args.file == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(args.file, "rb") as fh:
                data = fh.read()
    except OSError as exc:
        parser.error(str(exc))

    if args.n < 1:
        parser.error("MIN must be >= 1")

    fmt = {"d": "{:d} {}", "o": "{:o} {}", "x": "{:x} {}"}
    out = sys.stdout
    for offset, text in find_strings(data, args.n):
        if args.t:
            out.write(fmt[args.t].format(offset, text))
        else:
            out.write(text)
        out.write("\n")


if __name__ == "__main__":
    main()

